  traceBlocks(i).bits.ftqIdx.foreach(_ := rawInfo(i).ftqIdx)
  traceBlocks(i).bits.ftqOffset.foreach(_ := rawInfo(i).ftqOffset)
  traceBlockInPipe(i).itype := rawInfo(i).traceBlockInPipe.itype
